<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch } from 'vue'
import Viewport from './Viewport.vue'
import { state, selected, collisionSelection, history, checkpoint, add, duplicate, remove, edit, undo, redo, save, load, createRoom, editRoom, toggleWall, toggleCollisions, toggleSelectedCollisions, editStructuralColor, isStructural, isOpening, labels, snapSelected, wallContacts, beginRotation, endRotation, type ObjectKind, type Room, type Box } from './editor'
const viewport=ref<InstanceType<typeof Viewport>>();const file=ref<HTMLInputElement>();const currentView=ref('Perspectiva')
const roomFields:{key:'width'|'depth'|'height'|'thickness';label:string}[]=[{key:'width',label:'Anchura interior'},{key:'depth',label:'Profundidad interior'},{key:'height',label:'Altura de las paredes'},{key:'thickness',label:'Grosor de las paredes'}]
const wallFields:{key:keyof Room['walls'];label:string}[]=[{key:'north',label:'Norte · fondo'},{key:'south',label:'Sur · frente'},{key:'west',label:'Oeste · izquierda'},{key:'east',label:'Este · derecha'}]
const additions:{type:ObjectKind;label:string;icon:string}[]=[{type:'door',label:'Puerta',icon:'▯'},{type:'window',label:'Ventana',icon:'⊞'},{type:'column',label:'Columna',icon:'▥'},{type:'beam',label:'Viga',icon:'━'}]
const icons:Record<ObjectKind,string>={box:'◇',door:'▯',window:'⊞',column:'▥',beam:'━'}
const rotationFields:{key:'rotationX'|'rotationY'|'rotationZ';label:string}[]=[{key:'rotationX',label:'X · inclinación frontal'},{key:'rotationY',label:'Y · giro horizontal'},{key:'rotationZ',label:'Z · inclinación lateral'}]
const fields:{key:keyof Box;label:string}[]=[{key:'x',label:'X · izquierda / derecha'},{key:'y',label:'Y · altura desde el suelo'},{key:'z',label:'Z · delante / detrás'},{key:'width',label:'Anchura'},{key:'height',label:'Altura'},{key:'depth',label:'Profundidad'}]
function changeCollisions(e:Event){toggleCollisions();(e.target as HTMLInputElement).checked=collisionSelection.value.checked;(e.target as HTMLInputElement).indeterminate=collisionSelection.value.mixed}
function changeObjectCollisions(e:Event){toggleSelectedCollisions();(e.target as HTMLInputElement).checked=(selected.value?.collisions??state.collisions)}
function resetInput(e:Event,value:unknown){(e.target as HTMLInputElement).value=String(value??'')}
function resetRotationInput(e:Event,key:'rotationX'|'rotationY'|'rotationZ'){resetInput(e,selected.value?.[key]??0);endRotation()}
function resetRoomInput(e:Event,key:'width'|'depth'|'height'|'thickness'){resetInput(e,state.room?.[key])}
function resetObjectInput(e:Event,key:keyof Box){resetInput(e,selected.value?.[key])}
function commitPosition(e:Event,key:keyof Box){snapSelected([key as 'x'|'y'|'z']);resetObjectInput(e,key)}
function input(e:Event){return (e.target as HTMLInputElement).value}
function changeView(){viewport.value?.view(currentView.value)}
function key(e:KeyboardEvent){if((e.target as HTMLElement).matches('input,select,textarea'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate()}if(!e.ctrlKey&&!e.metaKey&&!e.altKey){if(e.key.toLowerCase()==='r'&&selected.value&&!isOpening(selected.value))state.transformMode='rotate';if(e.key.toLowerCase()==='w')state.transformMode='translate'}if(e.key==='Delete')remove();if(e.key==='Escape')state.selected=''}
watch(selected,object=>{if(!object||isOpening(object))state.transformMode='translate'})
onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>window.removeEventListener('keydown',key))
</script>
<template>
<div class="app"><header><a class="brand" href="/">▦ <span>gridly<span class="dot">.</span></span></a><div class="project-name">Mi espacio <span class="badge">MVP 08</span></div><div class="header-actions"><button @click="file?.click()">Abrir</button><button class="primary" @click="save">↓ Guardar proyecto</button><input ref="file" hidden type="file" accept=".json" @change="e=>{const f=(e.target as HTMLInputElement).files?.[0];if(f)load(f);(e.target as HTMLInputElement).value=''}"></div></header>
<div class="workspace"><aside class="objects-panel"><div class="section-title">ESCENA <span>{{state.objects.length + (state.room ? 1 : 0)}}</span></div><h2>Primero, tu habitación.</h2><p class="muted">Define el espacio y después añade tus muebles.</p><button v-if="!state.room" class="add-button" @click="createRoom">＋ Crear habitación</button><button v-else :class="['object-row','room-row',{active:state.selected==='room'}]" @click="state.selected='room'"><span class="object-icon">▱</span><span>Habitación<small>{{state.room.width / 1000}} × {{state.room.depth / 1000}} m</small></span></button><div class="construction-title">CONSTRUCCIÓN</div><div class="construction-buttons"><button v-for="item in additions" :key="item.type" :disabled="(item.type==='door'||item.type==='window')&&!state.room" @click="add(item.type)"><span>{{item.icon}}</span> {{item.label}}</button></div><button class="add-button" @click="add('box')">＋ Añadir prisma</button><div class="object-list"><button v-for="o in state.objects" :key="o.id" :class="['object-row',{active:state.selected===o.id}]" @click="state.selected=o.id"><span class="object-icon">{{icons[o.type??'box']}}</span><span>{{o.name}}</span><span class="swatch" :style="{background:o.color}"></span></button><p v-if="!state.objects.length" class="muted">Tu habitación está lista para amueblar.</p></div><div class="sidebar-bottom"><span class="green-dot"></span> Medidas en milímetros<p>Y indica el punto más bajo del objeto, también cuando está girado.</p></div></aside>
<main><div class="toolbar"><div><button :class="{active:state.transformMode==='translate'}" title="Mover (W)" aria-label="Mover" @click="state.transformMode='translate'">↔</button><button :class="{active:state.transformMode==='rotate'}" :disabled="!selected||isOpening(selected)" title="Rotar (R)" aria-label="Rotar" @click="state.transformMode='rotate'">⟳</button><button title="Deshacer (Ctrl+Z)" :disabled="!history.undo" @click="undo">↶</button><button title="Rehacer (Ctrl+Mayús+Z)" :disabled="!history.redo" @click="redo">↷</button><span class="separator"></span><label class="snap" title="Activar o desactivar las colisiones de los elementos opcionales. Vigas y columnas colisionan con otros tipos, pero pueden solaparse entre sí. Un estado mixto indica ajustes individuales."><input :checked="collisionSelection.checked" :indeterminate="collisionSelection.mixed" :aria-checked="collisionSelection.mixed?'mixed':collisionSelection.checked" type="checkbox" @change="changeCollisions"> Colisiones</label><label class="snap"><input v-model="state.snap" type="checkbox"> Snap</label><select v-model="state.step" aria-label="Paso de snap"><option :value="10">10 mm</option><option :value="50">50 mm</option><option :value="100">100 mm</option></select><label class="snap" title="Ajustar caras a paredes, suelo y altura de la habitación (60 mm)"><input v-model="state.wallSnap" :disabled="!state.snap" type="checkbox"> Paredes</label></div><select v-model="currentView" aria-label="Vista de cámara" @change="changeView"><option>Perspectiva</option><option>Superior</option><option>Frontal</option><option>Lateral</option></select></div><div class="canvas-wrap"><Viewport ref="viewport"/><div class="scene-label"><span class="green-dot"></span> ESPACIO DE TRABAJO <small>Cuadrícula · 500 mm</small></div><div v-if="state.collisionBlocked" class="collision-notice" role="status">Transformación limitada por una colisión</div><div class="navigation-help">Arrastrar: orbitar <span>·</span> Botón derecho: desplazar <span>·</span> Rueda: zoom</div></div><footer><span>{{state.selected==='room'?'Habitación':selected?selected.name:'Ningún objeto seleccionado'}}</span><span>{{state.selected === 'room' ? 'Edita las medidas interiores en el panel de propiedades' : state.transformMode==='rotate'?'Arrastra ⤾ X/Y/Z para rotar':'Cuadrados: tamaño · ✥: mover · ▲: elevar'}}</span></footer></main>
<aside class="properties"><div class="section-title">PROPIEDADES <span>mm</span></div><template v-if="state.selected==='room' && state.room"><h2>Habitación rectangular</h2><p class="muted">Las medidas corresponden al espacio interior libre. Las paredes crecen hacia fuera. El techo virtual limita las piezas a la altura de las paredes.</p><h3>Medidas del espacio</h3><label v-for="f in roomFields" :key="f.key" class="field">{{f.label}}<div class="number-field"><input type="number" min="1" max="100000" step="50" :value="state.room[f.key]" @focus="checkpoint" @input="e=>editRoom(f.key,input(e))" @blur="e=>resetRoomInput(e,f.key)"><span>mm</span></div></label><div class="room-summary">{{ (state.room.width * state.room.depth / 1000000).toFixed(2) }} m² <span>de superficie interior</span></div><h3>Paredes</h3><label v-for="wall in wallFields" :key="wall.key" class="wall-toggle"><input type="checkbox" :checked="state.room.walls[wall.key]" @change="toggleWall(wall.key)">{{wall.label}}</label><p class="muted">Las paredes cercanas a la cámara se ocultan para ver el interior. Siguen formando parte de la habitación.</p></template><template v-else-if="selected"><h2>{{labels[selected.type??'box']}}</h2><label class="field">Nombre<input :value="selected.name" @change="e=>edit('name',input(e))"></label><template v-if="isOpening(selected)"><h3>Ubicación en la pared</h3><label class="field">Pared<select :value="selected.wall" @change="e=>edit('wall',input(e))"><option v-for="wall in wallFields" :key="wall.key" :value="wall.key" :disabled="!state.room?.walls[wall.key]">{{wall.label}}</option></select></label><label class="field">Centro desde el inicio de la pared<div class="number-field"><input type="number" min="0" :step="state.step" :value="selected.offset" @focus="checkpoint" @input="e=>edit('offset',input(e),false)"><span>mm</span></div></label><label v-if="selected.type==='window'" class="field">Altura del alféizar<div class="number-field"><input type="number" min="0" :step="state.step" :value="selected.y" @focus="checkpoint" @input="e=>edit('y',input(e),false)"><span>mm</span></div></label><p class="muted">El inicio está a la izquierda en norte/sur y al fondo en este/oeste. El hueco se ajusta a los límites de la pared.</p><p v-if="!state.room?.walls[selected.wall!]" class="muted">Esta pared está desactivada. Actívala en Habitación para ver el elemento.</p></template><template v-else><h3>Posición</h3><p class="muted">Con Snap y Paredes activos, las caras se ajustan al acercarlas a 60 mm de una pared. También al confirmar la posición. Las paredes y el techo virtual bloquean el movimiento aunque Snap esté desactivado.</p><div v-if="wallContacts.length" class="snap-contact">{{ wallContacts.map(c=>c.label).join(' · ') }}</div><label v-for="f in fields.slice(0,3)" :key="f.key" class="field">{{f.label}}<div class="number-field"><input type="number" :min="f.key==='y'?0:undefined" :step="state.step" :value="selected[f.key]" @focus="checkpoint" @input="e=>edit(f.key,input(e),false)" @blur="e=>commitPosition(e,f.key)"><span>mm</span></div></label></template><h3>Dimensiones</h3><label v-for="f in fields.slice(3)" :key="f.key" class="field">{{f.key==='depth' && isOpening(selected) ? 'Profundidad del marco' : f.label}}<div class="number-field"><input type="number" min="1" step="10" :value="selected[f.key]" @focus="checkpoint" @input="e=>edit(f.key,input(e),false)" @blur="e=>resetObjectInput(e,f.key)"><span>mm</span></div></label><template v-if="!isOpening(selected)"><h3>Rotación</h3><p class="muted">Arrastra los controles flotantes siguiendo su aro de color o introduce los ángulos. El tamaño se adapta al espacio disponible mientras giras y recupera sus medidas iniciales cuando caben. Snap: pasos de 15°. W: mover.</p><label v-for="f in rotationFields" :key="f.key" class="field">{{f.label}}<div class="number-field"><input type="number" step="15" :value="selected[f.key]??0" @focus="beginRotation" @input="e=>edit(f.key,input(e),false)" @blur="e=>resetRotationInput(e,f.key)"><span>°</span></div></label></template><p v-else class="muted">La orientación de puertas y ventanas sigue la pared elegida para conservar el hueco.</p><template v-if="!isStructural(selected)"><h3>Colisiones</h3><label class="wall-toggle"><input type="checkbox" :checked="selected.collisions??state.collisions" @change="changeObjectCollisions">Colisiones de este elemento</label><p class="muted">Al desactivarlas, este elemento puede atravesar otros elementos opcionales. Las vigas, columnas, paredes y el techo siguen limitándolo.<template v-if="collisionSelection.mixed"> Hay elementos con colisiones activadas y otros desactivadas.</template></p><label class="color-field">Color del objeto<input type="color" :value="selected.color" @change="e=>edit('color',input(e))"></label></template><div class="object-actions"><button @click="duplicate">Duplicar</button><button class="danger" @click="remove">Eliminar</button></div></template><div v-else class="empty-properties"><span>◇</span><h2>Todo empieza con una pieza</h2><p>Selecciona un prisma en la escena para editar sus propiedades.</p></div><h3>Color de la estructura</h3><label class="color-field">Paredes, vigas y columnas<input type="color" :value="state.structuralColor" @change="e=>editStructuralColor(input(e))"></label></aside></div><div v-if="state.error || state.autosaveError" role="alert" class="error">{{state.error || state.autosaveError}}<button @click="state.error='';state.autosaveError=''">Cerrar</button></div></div>
</template>





